class Solution {
    private int gcd(int a,int b){
        while(b!=0){
            int temporary=a%b;
            a=b;
            b=temporary;
        }
        return a;
    }
    public long countPairs(int[] nums,int k){
        Map<Integer,Integer> frequency=new HashMap<>();
        long answer=0;
        for(int value:nums){
            int current=gcd(value,k);
            for(Map.Entry<Integer,Integer> entry:frequency.entrySet())if((long)current*entry.getKey()%k==0)answer+=entry.getValue();
            frequency.merge(current,1,Integer::sum);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    private fun gcd(first:Int,second:Int):Int{
        var a=first;
        var b=second;
        while(b!=0){
            val temporary=a%b;
            a=b;
            b=temporary
        };
        return a
    };
    fun countPairs(nums:IntArray,k:Int):Long{
        val frequency=HashMap<Int,Int>();
        var answer=0L;
        for(value in nums){
            val current=gcd(value,k);
            for((other,count) in frequency)if(current.toLong()*other%k==0L)answer+=count;
            frequency[current]=(frequency[current]?:0)+1
        };
        return answer
    }
}

